"use client"

import { useState } from "react"
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Pencil } from "lucide-react"

interface Record {
  firstName: string
  lastName: string
  phone: string
  email: string
  address: string
  state: string
  district: string
  city: string
  zip: string
}

export default function Home() {
  const [records, setRecords] = useState<Record[]>([
    { firstName: "John", lastName: "Doe", phone: "(208) 555-0112", email: "jonhd@gmail.com", address: "738 N JORDAN ST ALLENTOWN PA 18102–1841", state: "CA", district: "CA", city: "chicago", zip: "574855" },
    { firstName: "Jane", lastName: "Smith", phone: "(208) 555-0112", email: "janes@gmail.com", address: "738 N JORDAN ST ALLENTOWN PA 18102–1841", state: "CA", district: "CA", city: "san fransico", zip: "847595" },
  ])

  const [formData, setFormData] = useState<Record>({
    firstName: "",
    lastName: "",
    phone: "",
    email: "",
    address: "",
    state: "",
    district: "",
    city: "",
    zip: "",
  })

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value })
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    setRecords([...records, formData])
    setFormData({
      firstName: "",
      lastName: "",
      phone: "",
      email: "",
      address: "",
      state: "",
      district: "",
      city: "",
      zip: "",
    })
  }

  return (
    <Card className="w-full">
      <div className="flex gap-6 p-6">
        {/* Left Side - Form */}
        <div className="w-1/2 space-y-4">
          <CardHeader>
            <CardTitle className="text-sm font-medium">Add / Edit the single record Here</CardTitle>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSubmit} className="space-y-4">
              {/* First Name */}
              <div className="flex flex-col">
                <Label className="text-xs text-gray-500">First Name</Label>
                <Input name="firstName" value={formData.firstName} onChange={handleChange} className="w-full" />
              </div>

              {/* Last Name */}
              <div className="flex flex-col">
                <Label className="text-xs text-gray-500">Last Name</Label>
                <Input name="lastName" value={formData.lastName} onChange={handleChange} className="w-full" />
              </div>

              {/* Phone */}
              <div className="flex flex-col">
                <Label className="text-xs text-gray-500">Phone</Label>
                <Input name="phone" value={formData.phone} onChange={handleChange} className="w-full" />
              </div>

              {/* Email */}
              <div className="flex flex-col">
                <Label className="text-xs text-gray-500">Email</Label>
                <Input name="email" value={formData.email} onChange={handleChange} className="w-full" />
              </div>

              {/* Address */}
              <div className="flex flex-col">
                <Label className="text-xs text-gray-500">Address</Label>
                <Input name="address" value={formData.address} onChange={handleChange} className="w-full" />
              </div>

              {/* State, District, City, Zip in a single row */}
              <div className="flex gap-4">
                <div className="flex-1 flex flex-col">
                  <Label className="text-xs text-gray-500">State</Label>
                  <Input name="state" value={formData.state} onChange={handleChange} className="w-full" />
                </div>
                <div className="flex-1 flex flex-col">
                  <Label className="text-xs text-gray-500">District</Label>
                  <Input name="district" value={formData.district} onChange={handleChange} className="w-full" />
                </div>
                <div className="flex-1 flex flex-col">
                  <Label className="text-xs text-gray-500">City</Label>
                  <Input name="city" value={formData.city} onChange={handleChange} className="w-full" />
                </div>
                <div className="flex-1 flex flex-col">
                  <Label className="text-xs text-gray-500">Zip</Label>
                  <Input name="zip" value={formData.zip} onChange={handleChange} className="w-full" />
                </div>
              </div>

              {/* Buttons */}
              <div className="flex gap-2 pt-4">
                <Button variant="outline" type="button" className="w-1/2">Cancel</Button>
                <Button type="submit" className="w-1/2">Save</Button>
              </div>
            </form>

          </CardContent>
        </div>

        {/* Right Side - Table */}
        <div className="w-1/2">
          <CardHeader>
            <CardTitle className="text-sm font-medium">Show the List of records</CardTitle>
          </CardHeader>
          <CardContent className="overflow-x-auto">
            <Table className="min-w-full">
              <TableHeader>
                <TableRow>
                  <TableHead>Action</TableHead>
                  <TableHead>First Name</TableHead>
                  <TableHead>Last Name</TableHead>
                  <TableHead>Phone</TableHead>
                  <TableHead>Email</TableHead>
                  <TableHead className="max-w-xs">Address</TableHead>
                  <TableHead>City</TableHead>
                  <TableHead>Zip</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {records.map((record, index) => (
                  <TableRow key={index} className="hover:bg-gray-50">
                    <TableCell>
                      <Button variant="ghost" size="icon">
                        <Pencil className="h-4 w-4" />
                      </Button>
                    </TableCell>
                    <TableCell>{record.firstName}</TableCell>
                    <TableCell>{record.lastName}</TableCell>
                    <TableCell>{record.phone}</TableCell>
                    <TableCell>{record.email}</TableCell>
                    <TableCell className="truncate max-w-xs">{record.address}</TableCell>
                    <TableCell>{record.city}</TableCell>
                    <TableCell>{record.zip}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </CardContent>
        </div>
      </div>

    </Card>
  )
}
